    if (N === null) return;
    const M = nextInt();

    function readTree(numNodes) {
        const head = new Int32Array(numNodes + 1).fill(-1);
        const to = new Int32Array(2 * (numNodes - 1));
        const next = new Int32Array(2 * (numNodes - 1));
