            const v = nextInt();

            to[edgeCount] = v;
            next[edgeCount] = head[u];
            head[u] = edgeCount++;

            to[edgeCount] = u;
            next[edgeCount] = head[v];
            head[v] = edgeCount++;
        }

        return { numNodes, head, to, next };
    }

    const tree1 = readTree(N);
    const tree2 = readTree(M);

