            const u = q[qHead++];
            if (dist[u] > dist[farthestNode]) {
                farthestNode = u;
            }

            for (let e = head[u]; e !== -1; e = next[e]) {
                const v = to[e];
                if (dist[v] === -1) {
                    dist[v] = dist[u] + 1;
                    q[qTail++] = v;
                }
            }
        }

        // Segunda BFS a partir de farthestNode
        dist.fill(-1);
        parent.fill(0);
        qHead = 0;
        qTail = 0;
        const start = farthestNode;
        q[qTail++] = start;
        dist[start] = 0;

        let otherEnd = start;

        while (qHead < qTail) {
            const u = q[qHead++];
            if (dist[u] > dist[otherEnd]) {
                otherEnd = u;
            }

            for (let e = head[u]; e !== -1; e = next[e]) {
                const v = to[e];
                if (dist[v] === -1) {
                    dist[v] = dist[u] + 1;
                    parent[v] = u;
                    q[qTail++] = v;
                }
            }
        }

        // Reconstruir o caminho do diâmetro
        const diameterLength = dist[otherEnd];
        const stepsToCenter = Math.floor(diameterLength / 2);

        let curr = otherEnd;
        for (let i = 0; i < stepsToCenter; i++) {
            curr = parent[curr];
        }

        return curr;
    }

    const center1 = findCenter(tree1);
    const center2 = findCenter(tree2);

    console.log(`${center1} ${center2}`);
}

